use std::process::ExitCode;

use wgpu::util::DeviceExt;

const WORKGROUP: u32 = 8;

const SHADER: &str = r#"
struct Params {
    width: u32,
    height: u32,
    limit: u32,
    _pad: u32,
}

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read> xs: array<f32>;
@group(0) @binding(2) var<storage, read> ys: array<f32>;
@group(0) @binding(3) var<storage, read_write> times: array<u32>;

@compute @workgroup_size(8, 8, 1)
fn main(@builtin(global_invocation_id) id: vec3<u32>) {
    let i = id.x;
    let j = id.y;
    if (i >= params.width || j >= params.height) {
        return;
    }
    let cx = xs[i];
    let cy = ys[j];
    var zx = 0.0;
    var zy = 0.0;
    var n = 0u;
    loop {
        if (n >= params.limit || !(zx * zx + zy * zy <= 4.0)) {
            break;
        }
        let nx = zx * zx - zy * zy + cx;
        zy = 2.0 * zx * zy + cy;
        zx = nx;
        n = n + 1u;
    }
    times[j * params.width + i] = n;
}
"#;

struct Input {
    width: u32,
    height: u32,
    limit: u32,
    x_min: f64,
    x_max: f64,
    y_min: f64,
    y_max: f64,
}

fn parse_input(text: &str) -> Result<Input, String> {
    let mut lines = text.lines().filter(|l| !l.trim().is_empty());
    let first: Vec<&str> = lines
        .next()
        .ok_or("missing first line")?
        .split_whitespace()
        .collect();
    let second: Vec<&str> = lines
        .next()
        .ok_or("missing second line")?
        .split_whitespace()
        .collect();
    if first.len() != 3 {
        return Err("first line must hold <width> <height> <limit>".into());
    }
    if second.len() != 4 {
        return Err("second line must hold <x_min> <x_max> <y_min> <y_max>".into());
    }
    let int = |s: &str, name: &str, max: u32| -> Result<u32, String> {
        let v: u32 = s.parse().map_err(|_| format!("bad {name}: {s:?}"))?;
        if v < 1 || v > max {
            return Err(format!("{name} must be between 1 and {max}, got {v}"));
        }
        Ok(v)
    };
    let float = |s: &str, name: &str| -> Result<f64, String> {
        let v: f64 = s.parse().map_err(|_| format!("bad {name}: {s:?}"))?;
        if !v.is_finite() {
            return Err(format!("{name} must be finite"));
        }
        Ok(v)
    };
    let input = Input {
        width: int(first[0], "width", 1024)?,
        height: int(first[1], "height", 1024)?,
        limit: int(first[2], "limit", 1000)?,
        x_min: float(second[0], "x_min")?,
        x_max: float(second[1], "x_max")?,
        y_min: float(second[2], "y_min")?,
        y_max: float(second[3], "y_max")?,
    };
    if input.x_min >= input.x_max || input.y_min >= input.y_max {
        return Err("bounds must satisfy x_min < x_max and y_min < y_max".into());
    }
    Ok(input)
}

/// Coordinates of the cell centres along one axis, computed in double precision.
fn axis(min: f64, max: f64, count: u32) -> Vec<f32> {
    let step = (max - min) / f64::from(count);
    (0..count)
        .map(|k| (min + (f64::from(k) + 0.5) * step) as f32)
        .collect()
}

/// Runs the escape-time kernel on the GPU and returns one escape time per point, row-major.
async fn escape_times(input: &Input) -> Result<Vec<u32>, String> {
    let instance = wgpu::Instance::default();
    let adapter = instance
        .request_adapter(&wgpu::RequestAdapterOptions {
            power_preference: wgpu::PowerPreference::HighPerformance,
            ..Default::default()
        })
        .await
        .map_err(|e| format!("no GPU adapter: {e}"))?;
    let (device, queue) = adapter
        .request_device(&wgpu::DeviceDescriptor {
            label: None,
            required_limits: wgpu::Limits::downlevel_defaults().using_resolution(adapter.limits()),
            ..Default::default()
        })
        .await
        .map_err(|e| format!("cannot open GPU device: {e}"))?;

    let shader = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: Some("escape"),
        source: wgpu::ShaderSource::Wgsl(SHADER.into()),
    });
    let pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
        label: Some("escape"),
        layout: None,
        module: &shader,
        entry_point: Some("main"),
        compilation_options: Default::default(),
        cache: None,
    });

    let params: [u32; 4] = [input.width, input.height, input.limit, 0];
    let params_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("params"),
        contents: bytemuck::cast_slice(&params),
        usage: wgpu::BufferUsages::UNIFORM,
    });
    let xs = axis(input.x_min, input.x_max, input.width);
    let ys = axis(input.y_min, input.y_max, input.height);
    let xs_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("xs"),
        contents: bytemuck::cast_slice(&xs),
        usage: wgpu::BufferUsages::STORAGE,
    });
    let ys_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("ys"),
        contents: bytemuck::cast_slice(&ys),
        usage: wgpu::BufferUsages::STORAGE,
    });
    let count = input.width as usize * input.height as usize;
    let size = (count * std::mem::size_of::<u32>()) as wgpu::BufferAddress;
    let times_buf = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("times"),
        size,
        usage: wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC,
        mapped_at_creation: false,
    });
    let readback = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("readback"),
        size,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });

    let bind_group = device.create_bind_group(&wgpu::BindGroupDescriptor {
        label: Some("escape"),
        layout: &pipeline.get_bind_group_layout(0),
        entries: &[
            wgpu::BindGroupEntry {
                binding: 0,
                resource: params_buf.as_entire_binding(),
            },
            wgpu::BindGroupEntry {
                binding: 1,
                resource: xs_buf.as_entire_binding(),
            },
            wgpu::BindGroupEntry {
                binding: 2,
                resource: ys_buf.as_entire_binding(),
            },
            wgpu::BindGroupEntry {
                binding: 3,
                resource: times_buf.as_entire_binding(),
            },
        ],
    });

    let mut encoder = device.create_command_encoder(&wgpu::CommandEncoderDescriptor::default());
    {
        let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor::default());
        pass.set_pipeline(&pipeline);
        pass.set_bind_group(0, &bind_group, &[]);
        pass.dispatch_workgroups(
            input.width.div_ceil(WORKGROUP),
            input.height.div_ceil(WORKGROUP),
            1,
        );
    }
    encoder.copy_buffer_to_buffer(&times_buf, 0, &readback, 0, size);
    queue.submit(Some(encoder.finish()));

    let slice = readback.slice(..);
    let (tx, rx) = std::sync::mpsc::channel();
    slice.map_async(wgpu::MapMode::Read, move |r| {
        let _ = tx.send(r);
    });
    device
        .poll(wgpu::PollType::wait_indefinitely())
        .map_err(|e| format!("GPU poll failed: {e}"))?;
    rx.recv()
        .map_err(|e| format!("readback lost: {e}"))?
        .map_err(|e| format!("cannot map readback buffer: {e}"))?;
    let times = bytemuck::cast_slice::<u8, u32>(&slice.get_mapped_range()).to_vec();
    readback.unmap();
    Ok(times)
}

fn run() -> Result<(), String> {
    let path = std::env::args()
        .nth(1)
        .ok_or("usage: escape <input-file>")?;
    let text = std::fs::read_to_string(&path).map_err(|e| format!("cannot read {path}: {e}"))?;
    let input = parse_input(&text)?;
    let times = pollster::block_on(escape_times(&input))?;

    let limit = input.limit;
    let mut inside = 0u64;
    let mut bins = [0u64; 8];
    let mut sum = 0u64;
    let mut escaped = 0u64;
    for &n in &times {
        if n >= limit {
            inside += 1;
        } else {
            bins[(8 * n / limit) as usize] += 1;
            sum += u64::from(n);
            escaped += 1;
        }
    }
    let mean = if escaped == 0 {
        0.0
    } else {
        sum as f64 / escaped as f64
    };

    println!("INSIDE {inside}");
    for (k, c) in bins.iter().enumerate() {
        println!("BIN {k} {c}");
    }
    println!("MEAN {mean:.3}");
    Ok(())
}

fn main() -> ExitCode {
    match run() {
        Ok(()) => ExitCode::SUCCESS,
        Err(e) => {
            eprintln!("error: {e}");
            ExitCode::FAILURE
        }
    }
}

